export const paAdditionalQuestions: Question[] = items.map((row) => {
  const choices = [row.answer, ...row.distractors];
  const reasons = [row.explanation, ...row.feedback];
  const offset = row.id % 3;
  const order = [0, 1, 2].map((index) => (index + offset) % 3);
  const correctIndex = order.indexOf(0);
  const letters = ["A", "B", "C"] as const;
  const sourceUrl = row.reference.startsWith("57") ? lawUrl : rulesUrl;
  return {
    question_id: `pa-${String(row.id).padStart(3, "0")}`,
    state: "PA",
    exam_area: row.area,
    study_topic: row.study,
    topic: row.topic,
    difficulty: row.id % 5 === 0 ? "hard" : "medium",
    question_text: row.text,
    option_a: choices[order[0]],
    option_b: choices[order[1]],
    option_c: choices[order[2]],
    option_d: "",
    correct_option: letters[correctIndex],
    explanation: row.explanation,
    option_feedback: { A: reasons[order[0]], B: reasons[order[1]], C: reasons[order[2]], D: "" },
    source_id: "pa-official",
    source_reference: `${row.reference}. ${sourceUrl} Read 2026-11-12.`,
    effective_from: "2026-03-28",
    effective_to: null,
    last_verified_at: "2026-11-12",
    version: 1,
    is_free: [41, 61, 63, 77, 81, 99, 109, 129, 140, 153, 161, 174].includes(row.id),
    status: "published",
  };
});
